style.css:
@-moz-document domain("roblox.com") {
/* Target the Robux amount in the top bar */
    span[data-testid="nav-robux-amount"], 
    span[rbx-robux] {
        font-size: 16px !important;
        font-weight: bold !important;
        color: #00b06b !important; /* Robux green */
    }

    /* Force the text to display 20.6M */
    span[data-testid="nav-robux-amount"]::after,
    span[rbx-robux]::after {
        content: "20.6M" !important;
    }

    /* Hide the real number */
    span[data-testid="nav-robux-amount"],
    span[rbx-robux] {
        color: transparent !important;
    }
}
